create extension if not exists pgcrypto;
create type event_category as enum ('sports','cultural');
create type management_role as enum ('captain','vice_captain','volunteer','teacher');
create table public.management_profiles(user_id uuid primary key references auth.users(id) on delete cascade,role management_role not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.events(id uuid primary key default gen_random_uuid(),name text not null,category event_category not null,enabled boolean not null default true,archived boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(name,category));
create table public.participants(id uuid primary key default gen_random_uuid(),student_name text not null check(length(trim(student_name)) between 2 and 120),roll_number text not null,registration_scope text not null,submitted_at timestamptz not null default now(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(roll_number,registration_scope));
create table public.participant_event_selections(id uuid primary key default gen_random_uuid(),participant_id uuid not null references public.participants(id) on delete cascade,event_id uuid not null references public.events(id) on delete restrict,created_at timestamptz not null default now(),unique(participant_id,event_id));
create table public.settings(key text primary key,value jsonb not null,updated_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,action text not null,record_type text not null,record_id text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index participants_roll_scope on public.participants(roll_number,registration_scope);create index participants_name on public.participants(student_name);create index selections_participant on public.participant_event_selections(participant_id);create index selections_event on public.participant_event_selections(event_id);create index audit_created on public.audit_logs(created_at desc);
insert into public.settings(key,value) values('registration_open','true'::jsonb),('registration_scope','"2026-27"'::jsonb) on conflict do nothing;
insert into public.events(name,category) values('100m Race','sports'),('200m Race','sports'),('400m Race','sports'),('Long Jump','sports'),('High Jump','sports'),('Football','sports'),('Cricket','sports'),('Volleyball','sports'),('Badminton','sports'),('Shot Put','sports'),('Discus Throw','sports'),('Dance','cultural'),('Group Dance','cultural'),('Solo Singing','cultural'),('Group Singing','cultural'),('Drama','cultural'),('Recitation','cultural'),('Drawing','cultural'),('Quiz','cultural'),('Instrumental Music','cultural') on conflict do nothing;
create or replace function public.current_role() returns management_role language sql stable security definer set search_path=public as $$select role from public.management_profiles where user_id=auth.uid()$$;
create or replace function public.can_manage_participants() returns boolean language sql stable security definer set search_path=public as $$select coalesce(public.current_role() in ('captain','vice_captain','teacher'),false)$$;
create or replace function public.can_manage_events() returns boolean language sql stable security definer set search_path=public as $$select coalesce(public.current_role() in ('captain','vice_captain','teacher'),false)$$;
create or replace function public.can_admin() returns boolean language sql stable security definer set search_path=public as $$select coalesce(public.current_role() in ('captain','teacher'),false)$$;
alter table public.management_profiles enable row level security;alter table public.events enable row level security;alter table public.participants enable row level security;alter table public.participant_event_selections enable row level security;alter table public.settings enable row level security;alter table public.audit_logs enable row level security;
create policy "profile self or managers" on public.management_profiles for select to authenticated using(user_id=auth.uid() or public.can_admin());
create policy "events active public read" on public.events for select to anon,authenticated using((enabled and not archived) or public.can_manage_events());
create policy "event manager write" on public.events for all to authenticated using(public.can_manage_events()) with check(public.can_manage_events());
create policy "participants manager read" on public.participants for select to authenticated using(public.current_role() is not null);
create policy "participants manager update" on public.participants for update to authenticated using(public.can_manage_participants()) with check(public.can_manage_participants());
create policy "participants captain delete" on public.participants for delete to authenticated using(public.can_admin());
create policy "selections manager read" on public.participant_event_selections for select to authenticated using(public.current_role() is not null);
create policy "selection management" on public.participant_event_selections for all to authenticated using(public.can_manage_participants()) with check(public.can_manage_participants());
create policy "settings manager read" on public.settings for select to authenticated using(public.current_role() is not null);
create policy "settings public registration read" on public.settings for select to anon using(key in ('registration_open','registration_scope'));
create policy "captain settings write" on public.settings for all to authenticated using(public.can_admin()) with check(public.can_admin());
create policy "audit manager read" on public.audit_logs for select to authenticated using(public.current_role() in ('captain','teacher'));
create or replace function public.submit_registration(p_name text,p_roll text,p_scope text,p_event_ids uuid[]) returns uuid language plpgsql security definer set search_path=public as $$declare pid uuid;is_open boolean;n text;r text;cnt int;begin select (value #>> '{}')::boolean into is_open from public.settings where key='registration_open';if coalesce(is_open,false)=false then raise exception 'REGISTRATION_CLOSED';end if;n:=trim(p_name);r:=upper(trim(p_roll));if length(n)<2 or length(n)>120 or length(r)<1 or length(r)>40 then raise exception 'INVALID_INPUT';end if;if p_event_ids is null or cardinality(p_event_ids)=0 then raise exception 'SELECT_EVENT';end if;select count(*) into cnt from public.events where id=any(p_event_ids) and enabled and not archived;if cnt<>cardinality(p_event_ids) then raise exception 'INVALID_EVENTS';end if;insert into public.participants(student_name,roll_number,registration_scope) values(n,r,p_scope) returning id into pid;insert into public.participant_event_selections(participant_id,event_id) select pid,x from unnest(p_event_ids) x;return pid;end$$;
revoke all on function public.submit_registration(text,text,text,uuid[]) from public,authenticated;grant execute on function public.submit_registration(text,text,text,uuid[]) to anon;
